/* @lc app=leetcode id=1926 lang=kotlin */ class Solution { fun w(m: Array<CharArray>, p: IntArray) { m[p[0]][p[1]] = '+' } fun nearestExit(maze: Array<CharArray>, entrance: IntArray): Int = w(maze, entrance).let { generateSequence(listOf(entrance)) { f -> f.flatMap { p -> listOf(intArrayOf(1, 0), intArrayOf(-1, 0), intArrayOf(0, 1), intArrayOf(0, -1)).map { intArrayOf(p[0] + it[0], p[1] + it[1]) } }.filter { it[0] in maze.indices && it[1] in maze[0].indices && maze[it[0]][it[1]] == '.' }.distinctBy { it[0] * maze[0].size + it[1] }.onEach { w(maze, it) }.takeIf { it.isNotEmpty() } }.drop(1).indexOfFirst { f -> f.any { it[0] == 0 || it[1] == 0 || it[0] == maze.size - 1 || it[1] == maze[0].size - 1 } }.let { if (it < 0) -1 else it + 1 } } }